template.event:
local buttonState = element("ButtonState"):GetInt() if(buttonState ~= game.BUTTON_IDLE) then local buttonSize = 0.5*game.hudScale() local newTime = element("TickTimer"):GetFloat() + dt element("TickTimer"):SetFloat(newTime)
if(buttonState == game.BUTTON_PRESSED) then local size = lua_sys.smooth(buttonSize, buttonSize - 0.03, newTime*15) element["CloseImage"]("size"):SetFloat(size)
if(size == buttonSize - 0.03) then element("ButtonState"):SetInt(game.BUTTON_IDLE) end elseif(buttonState == game.BUTTON_RELEASED) then if(newTime < 0.1) then local size = lua_sys.smooth(buttonSize - 0.03, buttonSize + 0.05, newTime*20) element["CloseImage"]("size"):SetFloat(size)
elseif(newTime < 0.3) then local size = lua_sys.smooth(buttonSize + 0.05, buttonSize, (newTime-0.1)*20) element["CloseImage"]("size"):SetFloat(size)
if(size == buttonSize) then element("ButtonState"):SetInt(game.BUTTON_IDLE) end else element["CloseImage"]("size"):SetFloat(buttonSize) element("ButtonState"):SetInt(game.BUTTON_IDLE) end end end if(element("ButtonMapping"):GetInt() ~= 0) then if(not element["Touch"]:onTop() and element("buttonDown"):GetInt() ~= 0) then element("buttonDown"):SetInt(0) element["Touch"]:DoStoredScript("onTouchRelease") end end
